selected.compute:
options=read('/input/options')
result=[]
for c in combinations(options,3):
 valid_combo=True
 for f in ['worker','job']:
  vals=[c[i][f] for i in range(3)]
  if vals[0]==vals[1] or vals[1]==vals[2] or vals[0]==vals[2]:
   valid_combo=False
   break
 if not valid_combo:
  continue
 ids=[opt['id'] for opt in c]
 if valid(ids):
  result=ids
  break

selected.effects:
if result!=[]:
 write('/output/selection',result)
 send('report','team',result)
 if exists('/tmp/cache'):
  delete('/tmp/cache')
